-- =============================================================================================
-- Hand-written below this line: the submitter belongs to the party (an owner of the unit, or a
-- tenant of the tenancy, today in the property's time zone), at most 10 pending submissions per
-- party, decided once by someone other than the submitter, a confirmation names a BANK_TRANSFER
-- payment of the same unit, party, amount and currency, row-level security and grants. See
-- docs/architecture/DATA_MODEL.md section 6 (Residents' finance).
-- =============================================================================================

ALTER TABLE "bank_transfer_submissions" ADD CONSTRAINT "bank_transfer_submissions_amount_positive"
  CHECK ("amount_minor" > 0);
ALTER TABLE "bank_transfer_submissions" ADD CONSTRAINT "bank_transfer_submissions_currency_format"
  CHECK ("currency" ~ '^[A-Z]{3}$');
ALTER TABLE "bank_transfer_submissions" ADD CONSTRAINT "bank_transfer_submissions_party"
  CHECK (("paid_by" = 'TENANTS') = ("tenancy_id" IS NOT NULL));
ALTER TABLE "bank_transfer_submissions" ADD CONSTRAINT "bank_transfer_submissions_reference_trimmed"
  CHECK ("reference" = btrim("reference") AND length("reference") BETWEEN 1 AND 100);
ALTER TABLE "bank_transfer_submissions" ADD CONSTRAINT "bank_transfer_submissions_note_trimmed"
  CHECK ("note" IS NULL OR ("note" = btrim("note") AND length("note") BETWEEN 1 AND 500));
ALTER TABLE "bank_transfer_submissions" ADD CONSTRAINT "bank_transfer_submissions_reason_trimmed"
  CHECK ("rejection_reason" IS NULL
         OR ("rejection_reason" = btrim("rejection_reason") AND length("rejection_reason") BETWEEN 1 AND 500));
-- Decided once, by someone other than the submitter; a confirmation names its payment and a
-- rejection its reason. coalesce: a NULL comparison must fail the check, not pass it.
ALTER TABLE "bank_transfer_submissions" ADD CONSTRAINT "bank_transfer_submissions_decision"
  CHECK (
    ("status" = 'PENDING') = ("decided_at" IS NULL)
    AND ("status" = 'PENDING') = ("decided_by_user_id" IS NULL)
    AND coalesce("status" = 'PENDING' OR "decided_by_user_id" <> "submitted_by_user_id", false)
    AND ("status" = 'CONFIRMED') = ("payment_id" IS NOT NULL)
    AND ("status" = 'REJECTED') = ("rejection_reason" IS NOT NULL)
  );

CREATE FUNCTION app_bank_transfer_insert_check() RETURNS trigger
  LANGUAGE plpgsql
  AS $$
DECLARE
  prop record;
  local_today date;
  pending integer;
BEGIN
  IF NEW."status" <> 'PENDING' THEN
    RAISE EXCEPTION 'bank transfer submissions start pending' USING ERRCODE = 'check_violation';
  END IF;
  SELECT "currency", "time_zone" INTO prop FROM "properties" WHERE "id" = NEW."property_id";
  IF prop."currency" IS DISTINCT FROM NEW."currency" THEN
    RAISE EXCEPTION 'a bank transfer is in the property''s currency' USING ERRCODE = 'check_violation';
  END IF;
  local_today := (now() AT TIME ZONE prop."time_zone")::date;
  IF NEW."transferred_on" > local_today THEN
    RAISE EXCEPTION 'a bank transfer cannot be dated in the future' USING ERRCODE = 'check_violation';
  END IF;
  -- The submitter belongs to the party today: an owner of the unit, or a tenant of the tenancy
  -- (the same rules as app_resident_grants).
  IF NEW."paid_by" = 'OWNERS' AND NOT EXISTS (
    SELECT 1 FROM "ownerships" o JOIN "persons" p ON p."id" = o."person_id"
     WHERE o."unit_id" = NEW."unit_id" AND o."voided_at" IS NULL
       AND o."effective_from" <= local_today
       AND (o."effective_to" IS NULL OR o."effective_to" >= local_today)
       AND p."user_id" = NEW."submitted_by_user_id" AND p."status" = 'ACTIVE'
  ) THEN
    RAISE EXCEPTION 'only a current owner of the unit reports a transfer for its owners'
      USING ERRCODE = 'check_violation';
  END IF;
  IF NEW."paid_by" = 'TENANTS' AND NOT EXISTS (
    SELECT 1 FROM "tenancies" t
      JOIN "tenancy_occupants" oc ON oc."tenancy_id" = t."id"
      JOIN "persons" p ON p."id" = oc."person_id"
     WHERE t."id" = NEW."tenancy_id" AND t."unit_id" = NEW."unit_id" AND t."voided_at" IS NULL
       AND t."start_date" <= local_today AND (t."end_date" IS NULL OR t."end_date" >= local_today)
       AND p."user_id" = NEW."submitted_by_user_id" AND p."status" = 'ACTIVE'
  ) THEN
    RAISE EXCEPTION 'only a tenant of the current tenancy reports a transfer for it'
      USING ERRCODE = 'check_violation';
  END IF;
  -- At most 10 waiting per party (serialised per unit so two requests cannot both pass).
  PERFORM pg_advisory_xact_lock(hashtextextended('veyra.bank_transfer:' || NEW."unit_id"::text, 0));
  SELECT count(*) INTO pending FROM "bank_transfer_submissions"
   WHERE "unit_id" = NEW."unit_id" AND "paid_by" = NEW."paid_by"
     AND "tenancy_id" IS NOT DISTINCT FROM NEW."tenancy_id" AND "status" = 'PENDING';
  IF pending >= 10 THEN
    RAISE EXCEPTION 'too many bank transfers are waiting for finance' USING ERRCODE = 'check_violation';
  END IF;
  RETURN NEW;
END
$$;

CREATE TRIGGER "bank_transfer_submissions_insert_check"
  BEFORE INSERT ON "bank_transfer_submissions"
  FOR EACH ROW EXECUTE FUNCTION app_bank_transfer_insert_check();

-- Decided once; what the resident reported never changes; a confirmation names a BANK_TRANSFER
-- payment of the same unit, party, amount and currency.
CREATE FUNCTION app_bank_transfer_guard() RETURNS trigger
  LANGUAGE plpgsql
  AS $$
DECLARE
  pay record;
BEGIN
  IF OLD."status" <> 'PENDING'
     OR (NEW."organisation_id", NEW."property_id", NEW."unit_id", NEW."paid_by", NEW."tenancy_id",
         NEW."amount_minor", NEW."currency", NEW."transferred_on", NEW."reference", NEW."note",
         NEW."submitted_by_user_id", NEW."idempotency_key", NEW."created_at")
        IS DISTINCT FROM
        (OLD."organisation_id", OLD."property_id", OLD."unit_id", OLD."paid_by", OLD."tenancy_id",
         OLD."amount_minor", OLD."currency", OLD."transferred_on", OLD."reference", OLD."note",
         OLD."submitted_by_user_id", OLD."idempotency_key", OLD."created_at") THEN
    RAISE EXCEPTION 'bank transfer submission % is decided once and never changes', OLD."id"
      USING ERRCODE = 'check_violation';
  END IF;
  IF NEW."status" = 'CONFIRMED' THEN
    SELECT "unit_id", "paid_by", "tenancy_id", "method", "amount_minor", "currency" INTO pay
      FROM "payments" WHERE "id" = NEW."payment_id";
    IF pay."method" IS DISTINCT FROM 'BANK_TRANSFER' OR pay."unit_id" <> NEW."unit_id"
       OR pay."paid_by" <> NEW."paid_by" OR pay."tenancy_id" IS DISTINCT FROM NEW."tenancy_id"
       OR pay."amount_minor" <> NEW."amount_minor" OR pay."currency" <> NEW."currency" THEN
      RAISE EXCEPTION 'a confirmed transfer names a bank-transfer payment of the same unit, party and amount'
        USING ERRCODE = 'check_violation';
    END IF;
  END IF;
  RETURN NEW;
END
$$;

CREATE TRIGGER "bank_transfer_submissions_guard"
  BEFORE UPDATE ON "bank_transfer_submissions"
  FOR EACH ROW EXECUTE FUNCTION app_bank_transfer_guard();

-- ---------------------------------------------------------------------------------------------
-- Row-level security and grants. Submissions are never deleted.
-- ---------------------------------------------------------------------------------------------
ALTER TABLE "bank_transfer_submissions" ENABLE ROW LEVEL SECURITY;
ALTER TABLE "bank_transfer_submissions" FORCE ROW LEVEL SECURITY;
CREATE POLICY "bank_transfer_submissions_select" ON "bank_transfer_submissions" FOR SELECT
  USING (organisation_id = app_current_organisation_id());
CREATE POLICY "bank_transfer_submissions_insert" ON "bank_transfer_submissions" FOR INSERT
  WITH CHECK (organisation_id = app_current_organisation_id());
CREATE POLICY "bank_transfer_submissions_update" ON "bank_transfer_submissions" FOR UPDATE
  USING (organisation_id = app_current_organisation_id())
  WITH CHECK (organisation_id = app_current_organisation_id());

REVOKE ALL ON "bank_transfer_submissions" FROM PUBLIC;
GRANT SELECT, INSERT, UPDATE ON "bank_transfer_submissions" TO veyra_app;
